export const SOLUTIONS = {"12-1":{"ch":12,"entry":"blue_sky_game.py","mode":"run","reason":null,"files":{"blue_sky_game.py":"import sys\n\nimport pygame\n\nfrom settings import Settings\n\n\nclass BlueSkyGame:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n            (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Blue Sky Game\")\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            # Watch for keyboard and mouse events.\n            for event in pygame.event.get():\n                if event.type == pygame.QUIT:\n                    sys.exit()\n\n            # Redraw the screen during each pass through the loop.\n            self.screen.fill(self.settings.bg_color)\n\n            # Make the most recently drawn screen visible.\n            pygame.display.flip()\n            self.clock.tick(60)\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    bsg = BlueSkyGame()\n    bsg.run_game()","settings.py":"class Settings:\n    \"\"\"A class to store all settings for the game.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (40, 160, 200)"}},"12-2":{"ch":12,"entry":"blue_bird_game.py","mode":"run","reason":null,"files":{"bird.py":"import pygame\n \nclass Bird:\n    \"\"\"A class to manage the bird.\"\"\"\n \n    def __init__(self, bb_game):\n        \"\"\"Initialize the bird and set its starting position.\"\"\"\n        self.screen = bb_game.screen\n        self.screen_rect = bb_game.screen.get_rect()\n\n        # Load the bird image and get its rect.\n        #   Bird image from: https://opengameart.org/content/game-character-blue-flappy-bird-sprite-sheets\n        self.image = pygame.image.load('images/bird_small.bmp')\n        self.rect = self.image.get_rect()\n\n        # Start each new bird at the center of the screen.\n        self.rect.center = self.screen_rect.center\n\n    def blitme(self):\n        \"\"\"Draw the bird at its current location.\"\"\"\n        self.screen.blit(self.image, self.rect)","blue_bird_game.py":"import sys\n\nimport pygame\n\nfrom settings import Settings\nfrom bird import Bird\n\nclass BlueBirdGame:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n            (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Blue Bird Game\")\n\n        self.bird = Bird(self)\n\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            # Watch for keyboard and mouse events.\n            for event in pygame.event.get():\n                if event.type == pygame.QUIT:\n                    sys.exit()\n\n            # Redraw the screen during each pass through the loop.\n            self.screen.fill(self.settings.bg_color)\n            self.bird.blitme()\n\n            # Make the most recently drawn screen visible.\n            pygame.display.flip()\n            self.clock.tick(60)\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    bbg = BlueBirdGame()\n    bbg.run_game()","images/bird_small.bmp":{"b64":""},"settings.py":"class Settings:\n    \"\"\"A class to store all settings for the game.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (0, 0, 0)"}},"12-4":{"ch":12,"entry":"rocket_game.py","mode":"run","reason":null,"files":{"images/rocket.png":{"b64":""},"images/rocket_small.png":{"b64":""},"rocket.py":"import pygame\n \nclass Rocket:\n    \"\"\"A class to manage the rocket.\"\"\"\n \n    def __init__(self, r_game):\n        \"\"\"Initialize the rocket and set its starting position.\"\"\"\n        self.screen = r_game.screen\n        self.settings = r_game.settings\n        self.screen_rect = r_game.screen.get_rect()\n\n        # Load the rocket image and get its rect.\n        #   Rocket image from: https://opengameart.org/content/rocket\n        #   License: https://creativecommons.org/licenses/by/3.0/\n        #   Image was resized.\n        self.image = pygame.image.load('images/rocket_small.png')\n        self.rect = self.image.get_rect()\n\n        # Start each new rocket at the center of the screen.\n        self.rect.center = self.screen_rect.center\n\n        # Store a decimal value for the rocket's horizontal\n        #   and vertical positions.\n        self.x = float(self.rect.x)\n        self.y = float(self.rect.y)\n\n        # Movement flags.\n        self.moving_right, self.moving_left = False, False\n        self.moving_up, self.moving_down = False, False\n\n    def update(self):\n        \"\"\"Update the rocket's position based on movement flags.\"\"\"\n        if self.moving_right and self.rect.right < self.screen_rect.right:\n            self.x += self.settings.rocket_speed\n        if self.moving_left and self.rect.left > 0:\n            self.x -= self.settings.rocket_speed\n        if self.moving_up and self.rect.top > 0:\n            self.y -= self.settings.rocket_speed\n        if self.moving_down and self.rect.bottom <= self.screen_rect.bottom:\n            self.y += self.settings.rocket_speed\n\n        # Update rect object from position attributes.\n        self.rect.x = self.x\n        self.rect.y = self.y\n\n    def blitme(self):\n        \"\"\"Draw the rocket at its current location.\"\"\"\n        self.screen.blit(self.image, self.rect)","rocket_game.py":"import sys\n\nimport pygame\n\nfrom settings import Settings\nfrom rocket import Rocket\n\nclass RocketGame:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n            (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Rocket Game\")\n\n        self.rocket = Rocket(self)\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n            self.rocket.update()\n            self._update_screen()\n            self.clock.tick(60)\n    \n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                sys.exit()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n            elif event.type == pygame.KEYUP:\n                self._check_keyup_events(event)\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_RIGHT:\n            self.rocket.moving_right = True\n        elif event.key == pygame.K_LEFT:\n            self.rocket.moving_left = True\n        if event.key == pygame.K_UP:\n            self.rocket.moving_up = True\n        elif event.key == pygame.K_DOWN:\n            self.rocket.moving_down = True\n        elif event.key == pygame.K_q:\n            sys.exit()\n\n    def _check_keyup_events(self, event):\n        \"\"\"Respond to key releases.\"\"\"\n        if event.key == pygame.K_RIGHT:\n            self.rocket.moving_right = False\n        elif event.key == pygame.K_LEFT:\n            self.rocket.moving_left = False\n        if event.key == pygame.K_UP:\n            self.rocket.moving_up = False\n        elif event.key == pygame.K_DOWN:\n            self.rocket.moving_down = False\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        self.rocket.blitme()\n\n        pygame.display.flip()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    rg = RocketGame()\n    rg.run_game()","settings.py":"class Settings:\n    \"\"\"A class to store all settings for the game.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (255, 255, 255)\n\n        # Rocket settings.\n        self.rocket_speed = 1.5"}},"12-5":{"ch":12,"entry":"key_game.py","mode":"run","reason":null,"files":{"key_game.py":"import sys\n\nimport pygame\n\nfrom settings import Settings\n\n\nclass KeyGame:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n            (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Key Game\")\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n            self._update_screen()\n            self.clock.tick(60)\n    \n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                sys.exit()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        # Show the key that was pressed, then quit if q was pressed.\n        #   For more information about the output, see here:\n        #   https://www.pygame.org/docs/ref/key.html\n        print(event.key)\n        if event.key == pygame.K_q:\n            sys.exit()\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        pygame.display.flip()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    kg = KeyGame()\n    kg.run_game()","settings.py":"class Settings:\n    \"\"\"A class to store all settings for the game.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 600\n        self.screen_height = 400\n        self.bg_color = (40, 160, 200)\n"}},"12-6":{"ch":12,"entry":"sideways_shooter.py","mode":"run","reason":null,"files":{"bullet.py":"import pygame\nfrom pygame.sprite import Sprite\n \nclass Bullet(Sprite):\n    \"\"\"A class to manage bullets fired from the ship.\"\"\"\n\n    def __init__(self, ss_game):\n        \"\"\"Create a bullet object at the ship's current position.\"\"\"\n        super().__init__()\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n        self.color = self.settings.bullet_color\n\n        # Create a bullet rect at (0, 0) and then set correct position.\n        self.rect = pygame.Rect(0, 0, self.settings.bullet_width,\n            self.settings.bullet_height)\n        self.rect.midright = ss_game.ship.rect.midright\n        \n        # Store the bullet's position as a decimal value.\n        self.x = float(self.rect.x)\n\n    def update(self):\n        \"\"\"Move the bullet across the screen.\"\"\"\n        # Update the decimal position of the bullet.\n        self.x += self.settings.bullet_speed\n        # Update the rect position.\n        self.rect.x = self.x\n\n    def draw_bullet(self):\n        \"\"\"Draw the bullet to the screen.\"\"\"\n        pygame.draw.rect(self.screen, self.color, self.rect)\n","images/rocket_small.png":{"b64":""},"settings.py":"class Settings:\n    \"\"\"A class to store all settings for Sideways Shooter.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game's settings.\"\"\"\n        # Screen settings\n        self.screen_width = 1200\n        self.screen_height = 800\n        self.bg_color = (230, 230, 230)\n\n        # Ship settings\n        self.ship_speed = 1.5\n\n        # Bullet settings\n        self.bullet_speed = 3.0\n        self.bullet_width = 15\n        self.bullet_height = 3\n        self.bullet_color = (60, 60, 60)\n        self.bullets_allowed = 3","ship.py":"import pygame\n \nclass Ship:\n    \"\"\"A class to manage the ship.\"\"\"\n \n    def __init__(self, ss_game):\n        \"\"\"Initialize the ship and set its starting position.\"\"\"\n        self.screen = ss_game.screen\n        self.settings = ss_game.settings\n        self.screen_rect = ss_game.screen.get_rect()\n\n        # Load the ship image and get its rect.\n        self.image = pygame.image.load('images/rocket_small.png')\n        self.rect = self.image.get_rect()\n\n        # Start each new ship at the center of the left side of the screen.\n        self.rect.midleft = self.screen_rect.midleft\n\n        # Store a decimal value for the ship's vertical position.\n        self.y = float(self.rect.y)\n\n        # Movement flags\n        self.moving_up = False\n        self.moving_down = False\n\n    def update(self):\n        \"\"\"Update the ship's position based on movement flags.\"\"\"\n        # Update the ship's y value, not the rect.\n        if self.moving_up and self.rect.top > 0:\n            self.y -= self.settings.ship_speed\n        if self.moving_down and self.rect.bottom < self.screen_rect.bottom:\n            self.y += self.settings.ship_speed\n\n        # Update rect object from self.y.\n        self.rect.y = self.y\n\n    def blitme(self):\n        \"\"\"Draw the ship at its current location.\"\"\"\n        self.screen.blit(self.image, self.rect)\n","sideways_shooter.py":"import sys\n\nimport pygame\n\nfrom settings import Settings\nfrom ship import Ship\nfrom bullet import Bullet\n\nclass SidewaysShooter:\n    \"\"\"Overall class to manage game assets and behavior.\"\"\"\n\n    def __init__(self):\n        \"\"\"Initialize the game, and create game resources.\"\"\"\n        pygame.init()\n        self.clock = pygame.time.Clock()\n        self.settings = Settings()\n\n        self.screen = pygame.display.set_mode(\n                (self.settings.screen_width, self.settings.screen_height))\n        pygame.display.set_caption(\"Sideways Shooter\")\n\n        self.ship = Ship(self)\n        self.bullets = pygame.sprite.Group()\n\n    def run_game(self):\n        \"\"\"Start the main loop for the game.\"\"\"\n        while True:\n            self._check_events()\n            self.ship.update()\n            self._update_bullets()\n            self._update_screen()\n            self.clock.tick(60)\n\n    def _check_events(self):\n        \"\"\"Respond to keypresses and mouse events.\"\"\"\n        for event in pygame.event.get():\n            if event.type == pygame.QUIT:\n                sys.exit()\n            elif event.type == pygame.KEYDOWN:\n                self._check_keydown_events(event)\n            elif event.type == pygame.KEYUP:\n                self._check_keyup_events(event)\n\n    def _check_keydown_events(self, event):\n        \"\"\"Respond to keypresses.\"\"\"\n        if event.key == pygame.K_UP:\n            self.ship.moving_up = True\n        elif event.key == pygame.K_DOWN:\n            self.ship.moving_down = True\n        elif event.key == pygame.K_SPACE:\n            self._fire_bullet()\n        elif event.key == pygame.K_q:\n            sys.exit()\n\n    def _check_keyup_events(self, event):\n        \"\"\"Respond to key releases.\"\"\"\n        if event.key == pygame.K_UP:\n            self.ship.moving_up = False\n        elif event.key == pygame.K_DOWN:\n            self.ship.moving_down = False\n\n    def _fire_bullet(self):\n        \"\"\"Create a new bullet and add it to the bullets group.\"\"\"\n        if len(self.bullets) < self.settings.bullets_allowed:\n            new_bullet = Bullet(self)\n            self.bullets.add(new_bullet)\n\n    def _update_bullets(self):\n        \"\"\"Update position of bullets and get rid of old bullets.\"\"\"\n        # Update bullet positions.\n        self.bullets.update()\n\n        # Get rid of bullets that have disappeared.\n        for bullet in self.bullets.copy():\n            if bullet.rect.left >= self.screen.get_rect().right:\n                 self.bullets.remove(bullet)\n\n    def _update_screen(self):\n        \"\"\"Update images on the screen, and flip to the new screen.\"\"\"\n        self.screen.fill(self.settings.bg_color)\n        self.ship.blitme()\n        for bullet in self.bullets.sprites():\n            bullet.draw_bullet()\n\n        pygame.display.flip()\n\n\nif __name__ == '__main__':\n    # Make a game instance, and run the game.\n    ss_game = SidewaysShooter()\n    ss_game.run_game()"}}};
